INSERT INTO `news` VALUES (1, 'BỘ SƯU TẬP ÁO THUN ĐỘC QUYỀN ABC-MART × WHAT IT ISN\'T: NHỊP SỐNG NGÀY – ĐÊM CỦA SÀI GÒN', '“WHAT IT ISNT” là cụm từ bắt nguồn từ nghệ sĩ đường phố MARK GONZALES, có nghĩa là “...', '//abc-mart.com.vn/cdn/shop/articles/WII_11.jpg?v=1766029150&width=533', '2025-10-25', '<p dir=\"ltr\"><strong>“WHAT IT ISNT”</strong><span> là cụm từ bắt nguồn từ nghệ sĩ đường phố MARK GONZALES, có nghĩa là <strong>“</strong></span><strong>NÓ CÓ THỂ KHÔNG NHƯ NHỮNG GÌ BẠN MONG ĐỢI, NHƯNG HÃY CỐ GẮNG TRÂN TRỌNG NÓ</strong><span><strong>”</strong>.</span></p><p dir=\"ltr\"><strong>WHAT IT ISN’T là thương hiệu đại diện cho văn hóa và nghệ thuật đường phố tại Việt Nam, là nền tảng giao thoa giữa nghệ thuật và thời trang trên mỗi sản phẩm.</strong></p><p dir=\"ltr\" style=\"text-align: center;\"><strong><img src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/WII_1.jpg?v=1766022717\" alt=\"\" width=\"445\" height=\"556\" style=\"display: inline-block; margin-left: auto; margin-right: auto;\"></strong></p><h1 dir=\"ltr\" style=\"text-align: center;\"><strong>WHAT IT ISN\'T X ABC-MART</strong></h1><h1 dir=\"ltr\" style=\"text-align: center;\"><strong>“DAYS AND NIGHTS”</strong></h1><p dir=\"ltr\"><span>Sài Gòn – thành phố chưa bao giờ ngủ. Những con phố thay đổi diện mạo theo từng khoảnh khắc, dòng người chuyển động không ngừng, những câu chuyện được viết nên bởi ánh nắng ban ngày và ánh đèn rực rỡ mỗi đêm. Lấy cảm hứng từ chính nhịp sống đối lập nhưng hoà quyện ấy,</span><span> <strong>ABC-MART</strong></span><span> kế hợp cùng thương hiệu thời trang đường phố </span><strong>WHAT IT ISN’T</strong><span> ra mắt bộ sưu tập áo thun độc quyền </span><strong>DAYS AND NIGHTS</strong><span>, một cú bắt tay đầy cảm hứng giữa thời trang đường phố và tinh thần sống trẻ của người Sài Gòn.</span></p><div style=\"width: 100%; max-width: 600px; margin: 0 auto;\"><div style=\"position: relative; width: 100%; padding-bottom: 56.25%; height: 0; overflow: hidden;\"><iframe src=\"https://drive.google.com/file/d/13ctBYcEGHcmuc2hzWf15YgQI1H7s1qVQ/preview\" style=\"position: absolute; top: 0; left: 0; width: 100%; height: 100%; border:0;\"></iframe></div></div><h2 dir=\"ltr\"><strong>CÂU CHUYỆN ĐẰNG SAU BỘ SƯU TẬP</strong></h2><p dir=\"ltr\"><span>Bộ sưu tập được xây dựng dựa trên hai thái cực đặc trưng của Sài Gòn:</span></p><h3 dir=\"ltr\"><strong>🌤 Sài Gòn ban ngày – Năng động và rực rỡ</strong></h3><p dir=\"ltr\"><span>Những thiết kế mang sắc sáng, chi tiết đồ họa rõ nét và bố cục tối giản thể hiện nhịp sống hối hả, tràn đầy năng lượng. Mỗi chiếc áo thun là một lát cắt của thành phố: </span><span>tiếng xe máy dồn dập, mùi cà phê rang hòa trong không khí, những gánh hàng rong</span><span> quen thuộc.</span></p><p dir=\"ltr\"><span>Phiên bản </span><strong>DAYS</strong><span> tái hiện nhịp sống sôi động của Sài Gòn ban ngày nơi những con hẻm luôn đầy năng lượng.</span></p><p dir=\"ltr\"><span>Chiếc áo <strong>“</strong></span><strong>ĐÁ ME Tee</strong><span><strong>”</strong> là gửi gắm những khoảnh khắc tưởng chừng bình thường nhất nơi mọi thứ bắt đầu bằng một ly nước mát và một câu chuyện sáng.&nbsp;</span><b><br></b></p><h3 dir=\"ltr\"><span><img src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/WII_9.jpg?v=1766026245\" alt=\"\" style=\"max-width: 100%; height: auto;\"></span><strong>🌙 Sài Gòn ban đêm – Huyền bí và sống động</strong></h3><p dir=\"ltr\"><span>Đêm đến, Sài Gòn chuyển mình với sắc neon, bảng hiệu rực rỡ và âm thanh không dứt. Các thiết kế \"night mode\" trong bộ sưu tập khai thác màu tối, chất liệu phản quang và graphic mang cảm hứng nightlife – trẻ trung, cá tính và không ngại nổi bật.</span></p><p dir=\"ltr\"><span>Phiên bản </span><strong>NIGHTS</strong><span> tái hiện nhịp sống của những con hẻm về đêm nơi ánh đèn neon hắt lên mặt đường, bảng hiệu <em>“</em></span><em>Massage – Foot Relax</em><span><em>”</em> nhấp nháy trong hơi nóng của đô thị và những bước chân vẫn tiếp tục, không ngừng nghỉ.</span></p><p dir=\"ltr\"><span>Chiếc áo <strong>“</strong></span><strong>NO DAYS OFF</strong><span><strong>”</strong> Tee mang tinh thần ấy sống hết mình, làm hết sức, và tận hưởng từng khoảnh khắc dù là sau cùng của ngày.</span></p><h2 dir=\"ltr\"><span><img src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/WII_10.jpg?v=1766026440\" alt=\"\" style=\"max-width: 100%; height: auto;\"></span></h2><h2 dir=\"ltr\"><strong>THÔNG ĐIỆP CỦA BỘ SƯU TẬP: “Sáng mát-mẻ, tối mát-xa”</strong></h2><p dir=\"ltr\"><span>Bộ sưu tập áo thun </span><strong>DAYS AND NIGHTS</strong><span> mang năng lượng đường phố với thông điệp <strong>“</strong></span><strong>Sáng mát-mẻ, tối mát-xa</strong><span><strong>”</strong>. </span><span>Không chỉ là những chiếc áo thun, mà còn là lời kể về một thành phố luôn vận động. Đây là lựa chọn dành cho những ai yêu Sài Gòn, sống hết mình với từng khoảnh khắc và muốn mang tinh thần <strong>\"</strong></span><strong>ngày – đêm không ngủ</strong><span><strong>\"</strong> ấy theo cùng mọi nơi.</span></p><p dir=\"ltr\"><span><img src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/15.jpg?v=1766023775\" alt=\"\" width=\"445\" height=\"557\" style=\"display: block; margin-left: auto; margin-right: auto; max-width: 100%;\"></span></p><p dir=\"ltr\"><span>Câu chuyện thực tế từ những con hẻm không ngủ giữa lòng Sài Gòn, nơi mọi hoạt động và văn hoá đường phố diễn ra suốt ngày đêm từ những âm thanh, mùi vị, đến ánh sáng và cảm xúc đan xen.</span></p><p dir=\"ltr\"><span>Một sự kết hợp mang năng lượng đường phố sôi động dành cho những ai dám sống hết mình, cảm được nhịp sống của các con hẻm thành thị, nơi từng bước chân kể một câu chuyện, nơi văn hóa đường phố mang hơi thở rất riêng.</span></p><p dir=\"ltr\"><span>Bộ sưu tập <strong>“</strong></span><strong>DAYS AND NIGHTS</strong><span><strong>”</strong> là lời tôn vinh tinh thần ấy — năng động, phóng khoáng, và đậm chất đường phố.</span></p><p dir=\"ltr\"><span>📅 Chính thức mở bán từ 25.10.2025 tại toàn bộ cửa hàng, website của ABC-MART và What it isN\'t trên toàn quốc.</span></p><p dir=\"ltr\"><span>Mua ngay </span><span><span style=\"color: rgb(0, 102, 255);\"><strong><a href=\"https://abc-mart.com.vn/collections/what-it-isnt\" style=\"color: rgb(0, 102, 255);\">tại đây</a></strong></span>.</span></p><p>&nbsp;</p>', NULL, NULL, NULL, NULL);
INSERT INTO `news` VALUES (2, '[SỰ KIỆN] Không Gian Thời Trang Đường Phố Tại ABC-MART – Ngày 25/10/2025', 'Ngày 25/10 vừa qua, cửa hàng ABC-MART Saigon Centre đã trở thành điểm hẹn của những tín đồ yêu thích thời trang đường phố (street style)...', '//abc-mart.com.vn/cdn/shop/articles/1_34c58288-58d0-4412-b024-90beb9c55e90.jpg?v=1762223452&width=533', '2025-10-26', '<p dir=\"ltr\"><span>Ngày<strong>&nbsp;</strong></span><strong>25/10 vừa qua</strong><span>, cửa hàng </span><strong>ABC-MART Saigon Centre</strong><span> đã trở thành điểm hẹn của những tín đồ yêu thích </span><strong>thời trang đường phố</strong><span> (street style). Sự kiện </span><span>“<strong>ABC-MART Showcase 2025</strong>”</span><span> mang đến một không gian trưng bày năng động, trẻ trung, đậm tinh thần tự do và sáng tạo – đúng chất của văn hóa streetwear hiện đại.</span></p><p style=\"text-align: center;\" dir=\"ltr\"><span><img alt=\"\" src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/1_cc18ecdb-7898-44f8-afe0-befcfd5ecb7d.jpg?v=1762221683\"></span><em>Không gian thân mật tại sự kiện</em></p><p dir=\"ltr\"><span>Luôn tôn trọng và vinh danh tinh thần thời trang cá nhân, ABC-MART cùng thông điệp “STYLE BY U” - phong cách được định hình bởi bạn, chúng tôi hi vọng sẽ luôn là sân chơi thời trang để bạn tự do thể hiện cá tính và chất riêng.</span></p><h2 dir=\"ltr\"><span>🌟 Không Gian Trưng Bày Ấn Tượng</span></h2><p dir=\"ltr\"><span>Ngay từ lối vào, khách tham quan đã bị thu hút bởi </span><strong>thiết kế trưng bày độc đáo</strong><span>, những góc check-in đậm chất “cool”. Các sản phẩm chủ đạo trong mùa Thu - Đông 2025 cũng được sắp xếp trải dài cực đa dạng.</span></p><h2 dir=\"ltr\"><span><img alt=\"\" src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/2_4ea42707-1556-45ca-bda3-3c5d4d120343.jpg?v=1762221749\"></span></h2><h2 dir=\"ltr\"><span>Những Bộ Sưu Tập Nổi Bật</span></h2><p dir=\"ltr\"><span>Sự kiện lần này đánh dấu hành trình 3 năm hoạt động tại Việt Nam, </span><strong>ABC-MART vinh dự được hợp tác cùng What it isNt</strong><span> - thương hiệu nghệ thuật thời trang và văn hóa đường phố, </span><span>ra mắt <strong>bộ sưu tập áo thun độc quyền </strong></span><strong>“DAYS AND NIGHTS”</strong><span> lấy cảm hứng từ những con hẻm không ngủ của Sài Gòn, nơi nhịp sống và văn hoá đường phố vận hành suốt ngày đêm.</span></p><p dir=\"ltr\"><span>(Xem thêm thông tin về BST <span style=\"color: rgb(0, 102, 255);\"><strong><a href=\"https://abc-mart.com.vn/collections/what-it-isnt\" target=\"_blank\" style=\"color: rgb(0, 102, 255);\" rel=\"noopener\">tại đây</a></strong></span>)</span></p><p style=\"text-align: center;\" dir=\"ltr\"><span><img alt=\"\" src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/5.jpg?v=1762221856\"></span><em>Nữ diễn viên Katleen Phan Võ thích thú trải nghiệm mẫu áo “Days” thuộc BST</em></p><p dir=\"ltr\"><span>Tiếp nối hành trình phát triển, chúng tôi vui mừng khi được trở thành </span><strong>đơn vị bán lẻ đầu tiên phân phối dòng giày thời trang thể thao (Sportstyle) thuộc thương hiệu Mizuno tại thị trường Việt Nam</strong><span> - một bước mở rộng đáng chú ý trong phân khúc sản phẩm cao cấp tại ABC-MART.</span></p><p style=\"text-align: center;\" dir=\"ltr\"><span><img alt=\"\" src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/6.jpg?v=1762221947\"></span><em>Góc trưng bày dòng giày thời trang thể thao Mizuno</em></p><p dir=\"ltr\"><span>Không chỉ dừng lại ở đó, ABC-MART còn mang đến nhiều mẫu giày mới và độc quyền từ các thương hiệu nổi tiếng có mặt tại ABC-MART như </span><span><strong>New Balance</strong>,<strong> Asics</strong>, </span><span>… Mỗi sản phẩm đều mang chất riêng, khuyến khích giới trẻ thể hiện </span><strong>cá tính và phong cách sống tự do</strong><span> qua thời trang.</span></p><p dir=\"ltr\"><span>Nhằm tạo sự thuận tiện cho khách hàng trong việc nắm bắt thông tin về sản phẩm, ABC-MART đã phát hành ấn phẩm “</span><strong>ABC-MART Magazine</strong><span>” như một “</span><strong>kênh truyền thông thu nhỏ</strong><span>”. Ấn phẩm này có sẵn tại tất cả cửa hàng trên toàn quốc.</span></p><p dir=\"ltr\"><span><img alt=\"\" src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/3_dcd37e6c-b393-4cab-a8c6-dd17716369b9.jpg?v=1762221981\"></span><em>Thông tin thêm: Không gian trưng bày hoạt động đến hết ngày 09/11/2025 tại cửa hàng ABC-MART Grand Stage Saigon Centre (ô số 03, tầng B1, TTTM Saigon Centre, 65 Lê Lợi, phường Sài Gòn, TP.HCM) cho khách hàng tự do trải nghiệm sản phẩm.</em></p><h2 dir=\"ltr\"><span>📸 Hoạt Động Trải Nghiệm &amp; Check-in</span></h2><p dir=\"ltr\"><span>Không chỉ là buổi trưng bày và giới thiệu sản phẩm, khách tham quan còn được </span><strong>trải nghiệm mix &amp; match</strong><span> tự do, </span><strong>chụp ảnh check-in</strong><span>, và nhận những </span><strong>phần quà độc quyền</strong><span> từ ABC-MART. Khu vực photobooth được yêu thích nhất chính là góc “Magazine Photobooth” – nơi ai cũng có thể trở thành fashion icon trong vài bức hình.</span></p><p style=\"text-align: center;\" dir=\"ltr\"><span><img alt=\"\" src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/4_b0c1ecf2-4477-4dab-aa1d-bff653239eb2.jpg?v=1762222041\"></span><em>“Magazine Photobooth” ghi lại những khoảnh khắc đáng nhớ cùng khách mời và đối tác</em></p><h2 dir=\"ltr\"><span><img src=\"https://cdn.shopify.com/s/files/1/0885/1446/2062/files/7.jpg?v=1762222076\" alt=\"\"></span><b></b><span></span><span>Kết Lại Một Ngày Đầy Cảm Hứng</span></h2><p dir=\"ltr\"><span>Sự kiện kết thúc nhưng dư âm của một ngày tràn ngập năng lượng và cảm hứng vẫn còn đọng lại. </span><strong>ABC-MART</strong><span> một lần nữa khẳng định vị thế của mình không chỉ là cửa hàng bán lẻ giày dép và phụ kiện, mà còn là </span><strong>điểm chạm văn hóa thời trang đường phố</strong><span> dành cho giới trẻ yêu phong cách, yêu sự khác biệt.</span></p><p dir=\"ltr\"><span>Hãy theo dõi <span style=\"color: rgb(0, 102, 255);\"><strong><a href=\"https://www.facebook.com/ABCMARTVNOFFICIAL/\" style=\"color: rgb(0, 102, 255);\" rel=\"noopener\" target=\"_blank\">ABC-MART</a></strong></span> để không bỏ lỡ các sự kiện và bộ sưu tập mới nhất trong thời gian tới!</span><b></b></p>', NULL, NULL, NULL, NULL);
INSERT INTO `news` VALUES (3, 'TỰ DO THỂ HIỆN CHẤT RIÊNG VỚI CHUỖI SỰ KIỆN VANS X ABC-MART', 'Trong vòng chưa đầy một năm, Vans và ABC-MART đã cùng nhau tổ chức hai sự kiện sáng tạo cho cộng ...', '//abc-mart.com.vn/cdn/shop/articles/COVER_faca605f-bf4a-4874-96a7-72b6f5087d5c.jpg?v=1760320247&width=533', '2025-10-27', '', NULL, NULL, NULL, NULL);
